css:
.dcx,.dcx{margin:0;padding:0;background:#FFFFFF;font-family:'Plus Jakarta Sans',system-ui,sans-serif;color:#0B2018;-webkit-font-smoothing:antialiased}
.dcx a{color:#0B3B29;text-decoration:none}
.dcx a:hover{color:#0E8A52}
.dcx [data-z] div,.dcx [data-z] span,.dcx [data-z] a,.dcx [data-h1]{white-space:nowrap}
.dcx [data-z] p,.dcx [data-z] p *,.dcx [data-z] h2,.dcx [data-z] h2 *,.dcx [data-z] [data-wrap],.dcx [data-z] [data-wrap] *{white-space:normal}
@media (max-width:1040px){.dcx [data-scroll]{max-width:100%}
.dcx [data-c]{grid-template-columns:minmax(0,1fr)!important;row-gap:20px}
.dcx [data-c]>*{max-width:100%}
.dcx [data-hero]{flex-direction:column;align-items:center;height:auto!important;padding-bottom:24px}
.dcx [data-nav]{display:none!important}
.dcx [data-g4]{grid-template-columns:repeat(2,minmax(0,1fr))!important}
.dcx [data-steps]{grid-template-columns:minmax(0,1fr)!important;row-gap:16px}
.dcx [data-steps] [data-line]{display:none!important}
.dcx [data-hide]{display:none!important}
}
@media (max-width:600px){.dcx [data-v]{zoom:.6}
.dcx [data-g4]{grid-template-columns:minmax(0,1fr)!important}
.dcx [data-row]{flex-wrap:wrap}
.dcx [data-h1]{font-size:42px!important;line-height:44px!important}
}
.dcx [data-scroll]{overflow-y:hidden}

.dch-3d1ded89:hover{transform:translateY(-1px) !important;color:#FFFFFF !important}
.dch-df2ff70f:hover{transform:translateY(-2px) !important;color:#FFFFFF !important}
